function welcome(){stop();locked=false;app.innerHTML=`<button class="wc-text-button wc-change-type" data-action="types">← 월드컵 종류 선택</button><div class="wc-welcome"><div class="wc-art"><img src="/images/game/seeya-worldcup.png" alt="두 무대 사이에서 노래를 고르는 씨야 캐릭터" width="1672" height="941"><span>SEEYA WORLD CUP</span></div><section class="wc-start"><p class="wc-label">${rows.length}${E(unit())} · ${E(data.tag||'SEEYA SONGS')}</p><h2 tabindex="-1">${E(data.title)}</h2><p>${data.id==='film'?'더 마음에 남는 배역을 선택하세요.':data.id==='mv'?'두 영상을 보고 더 좋아하는 뮤비를 선택하세요.':data.id==='covers'?'두 무대를 보고 더 마음에 남는 무대를 선택하세요.':'두 곡을 들어보고 더 좋아하는 한 곡을 선택하세요.'}<br>${E(data.description)}</p><fieldset><legend>라운드 선택</legend>${data.rounds.map((n,i)=>`<label><input type="radio" name="wcSize" value="${n}" ${i===0?'checked':''}><b>${roundName(n)}</b><small>${n==='all'?rows.length+unit()+' 모두 참가':'매번 랜덤 '+n+unit()}</small></label>`).join('')}</fieldset>${stats.enabled?'<label class="wc-stat-opt"><input type="checkbox" id="wcJoinStats" checked> 전체 우승 통계에 이 게임 반영</label>':'<p class="wc-small">전체 통계 연결 준비 중 · 지금은 내 우승 기록만 저장됩니다.</p>'}<button class="wc-primary" data-action="start">새 월드컵 시작하기</button>${game?`<button class="wc-secondary" data-action="resume">${G.replay(game,ids,data.version).winner?'지난 결과 보기':`${G.roundProgress(G.replay(game,ids,data.version)).text} 이어하기`}</button>`:''}<button class="wc-text-button" data-action="rank">내 우승 기록 보기</button><button class="wc-secondary" data-action="global-rank">전체 우승 순위</button>${stats.pending().length?`<button class="wc-text-button" data-action="outbox">통계 등록 대기 ${stats.pending().length}건</button>`:''}<p class="wc-small">${E(data.scopeNote)}<br>대진은 매번 무작위입니다. 전체 참가는 모든 후보를 포함하며, 필요한 첫 라운드 부전승을 무작위로 배정합니다.</p></section></div><details class="wc-catalog"><summary>참가 후보 ${rows.length}${E(unit())} 확인하기</summary><div class="wc-song-list">${rows.map(r=>`<div>${r.image?rolePhoto(r,true):''}<strong>${E(r.title)}</strong><small>${E(r.artist?r.artist+' · '+r.album:r.album)}</small>${r.detail?`<small>${E(r.detail)}</small>`:''}${r.videoKind?`<small>${E(r.videoKind)} · ${E(r.channel)}</small>`:''}${source(r)}</div>`).join('')}</div></details>${data.pending?.length?`<details class="wc-catalog"><summary>추가 확인 중인 작품 ${data.pending.length}개</summary>${data.pending.map(r=>`<p><strong>${E(r.title)}</strong> · ${E(r.reason)} <a href="${E(r.source)}" target="_blank" rel="noopener noreferrer">확인한 보도 ↗</a></p>`).join('')}</details>`:''}`;}
function battle(){stop();locked=false;const s=G.replay(game,ids,data.version);if(s.winner)return result(s.winner,false);const pair=s.pair.map(id=>byId[id]),progress=G.roundProgress(s),label=progress.label;app.innerHTML=`<div class="wc-match-head"><div><p class="wc-label">${E(data.title)}</p><h2 tabindex="-1">${label} <span class="wc-match-counter">${progress.current}/${progress.matches}</span></h2></div><button class="wc-text-button" data-action="home">잠깐 쉬기</button></div><ol class="wc-round-path" aria-label="라운드 진행">${[64,32,16,8,4,2].filter(n=>n<=game.size).map(n=>`<li class="${n===s.round?'current':n>s.round?'finished':''}" ${n===s.round?'aria-current="step"':''}>${n===2?'결승':n+'강'}</li>`).join('')}</ol>${s.byes?`<p class="wc-bye-note">${rows.length}${E(unit())} 전체 참가 · 이 라운드 ${s.byes}${E(unit())} 부전승<br>진행 번호는 실제 선택하는 ${progress.matches}대결 기준입니다.</p>`:''}<div class="wc-progress"><progress aria-label="${label} 완료한 대결" max="${progress.matches}" value="${progress.completed}">${progress.completed}/${progress.matches}</progress></div><div class="wc-pair">${pair.map((r,i)=>`<article class="wc-contender" data-side="${i}"><div class="wc-contender-heading"><span class="wc-side-label">${i===0?'A':'B'}</span><div><h3>${E(r.title)}</h3><p>${E(r.artist?r.artist+' · '+r.album:r.album)}</p></div></div>${video(r,i)}<div class="wc-source">${r.officialReleaseUrl?`<a href="${E(r.officialReleaseUrl)}" target="_blank" rel="noopener noreferrer">SEEYA Official · 발표곡</a>`:`<span>${E([r.videoKind,r.channel].filter(Boolean).join(' · '))}</span>`}${source(r)}</div><button class="wc-pick" data-pick="${r.id}">${E(data.pickLabel||'이 곡 선택')} <span>♥</span><span class="sr-only"> · ${E(r.title)}</span></button></article>`).join('<span class="wc-vs" aria-hidden="true">VS</span>')}</div><p class="wc-hint">재생과 선택은 따로 할 수 있어요. 한 영상을 재생하면 다른 영상은 멈춥니다.</p>`;mountVideos(pair);focus();}
